CREATE TABLE IF NOT EXISTS certifications(id INTEGER PRIMARY KEY, student_id INTEGER NOT NULL REFERENCES students(id), sport TEXT NOT NULL, level INTEGER NOT NULL, granted_by INTEGER NOT NULL REFERENCES coaches(id), granted_at TEXT NOT NULL, expires_at TEXT, UNIQUE(student_id,sport,level));
CREATE TABLE IF NOT EXISTS assessments(id INTEGER PRIMARY KEY, student_id INTEGER NOT NULL REFERENCES students(id), session_id INTEGER NOT NULL REFERENCES course_sessions(id), examiner_id INTEGER NOT NULL REFERENCES coaches(id), sport TEXT NOT NULL, level INTEGER NOT NULL, status TEXT NOT NULL, score INTEGER NOT NULL DEFAULT 0, notes TEXT NOT NULL DEFAULT '', version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS assessment_student_idx ON assessments(student_id,sport,level,status);
CREATE TABLE IF NOT EXISTS equipment(id INTEGER PRIMARY KEY, asset_tag TEXT NOT NULL UNIQUE, kind TEXT NOT NULL, sport TEXT NOT NULL, size TEXT NOT NULL, status TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, last_inspected_at TEXT);
CREATE INDEX IF NOT EXISTS equipment_fit_idx ON equipment(sport,kind,size,status);
CREATE TABLE IF NOT EXISTS equipment_inspections(id INTEGER PRIMARY KEY, equipment_id INTEGER NOT NULL REFERENCES equipment(id), inspector_id INTEGER NOT NULL REFERENCES accounts(id), outcome TEXT NOT NULL, notes TEXT NOT NULL, inspected_at TEXT NOT NULL, valid_until TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS equipment_loans(id INTEGER PRIMARY KEY, equipment_id INTEGER NOT NULL REFERENCES equipment(id), student_id INTEGER NOT NULL REFERENCES students(id), session_id INTEGER NOT NULL REFERENCES course_sessions(id), issued_by INTEGER NOT NULL REFERENCES accounts(id), status TEXT NOT NULL, checked_out_at TEXT NOT NULL, returned_at TEXT, version INTEGER NOT NULL DEFAULT 1);
CREATE UNIQUE INDEX IF NOT EXISTS equipment_active_loan_idx ON equipment_loans(equipment_id) WHERE status='active';
CREATE TABLE IF NOT EXISTS maintenance_cases(id INTEGER PRIMARY KEY, equipment_id INTEGER NOT NULL REFERENCES equipment(id), loan_id INTEGER REFERENCES equipment_loans(id), opened_by INTEGER NOT NULL REFERENCES accounts(id), status TEXT NOT NULL, damage_code TEXT NOT NULL, responsibility TEXT NOT NULL, notes TEXT NOT NULL, opened_at TEXT NOT NULL, closed_at TEXT, version INTEGER NOT NULL DEFAULT 1);
CREATE INDEX IF NOT EXISTS maintenance_open_idx ON maintenance_cases(equipment_id,status);
CREATE TABLE IF NOT EXISTS makeup_entitlements(id INTEGER PRIMARY KEY, enrollment_id INTEGER NOT NULL UNIQUE REFERENCES enrollments(id), canceled_session_id INTEGER NOT NULL REFERENCES course_sessions(id), replacement_session_id INTEGER REFERENCES course_sessions(id), status TEXT NOT NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL);
